const page=document.body.dataset.page||'workspace';const routeFilters=new URLSearchParams(location.search);let data=[],query=routeFilters.get('q')||'',category=routeFilters.get('category')||'Все';function saveFilters(){const u=new URL(location.href);query?u.searchParams.set('q',query):u.searchParams.delete('q');category!=='Все'?u.searchParams.set('category',category):u.searchParams.delete('category');history.replaceState(null,'',u)}
