function searchToolbar(categories,rerender){const bar=el('div','ws-toolbar'),tabs=el('div','ws-tabs');for(const c of categories){const b=button(c,()=>{category=c;saveFilters();rerender()},category===c?'selected':'');tabs.append(b)}const search=el('label','ws-search');search.append(icon('search'));const input=el('input');input.placeholder='Поиск';input.setAttribute('aria-label','Поиск');input.value=query;input.oninput=e=>{query=e.target.value;saveFilters();rerender(true)};search.append(input);bar.append(tabs,search);return bar}
function empty(title,text,action){const e=el('div','ws-empty');e.append(icon('folder'),el('h2','',title),el('p','',text));if(action)e.append(button('Создать проект',()=>newProject(),'ws-primary'));return e}
function previewTemplate(t){const d=el('dialog','template-preview-dialog'),close=button('Закрыть',()=>d.close(),'ws-outline'),v=el('video');v.src=t.preview;v.poster=t.poster;v.controls=true;v.playsInline=true;v.autoplay=true;d.append(el('h2','',t.name),el('p','template-source-note','Видеошаблон / '+t.aspect+' / '+t.duration+' секунд'),v,close);document.body.append(d);d.onclose=()=>{v.pause();d.remove()};d.showModal()}
function poster(kind,name){const t=TEMPLATES.find(t=>t.visual===kind||t.name===name),v=el('div','template-art '+kind),image=el('img');image.src=t?.poster||'assets/footage/auto.jpg';image.alt=name;image.loading='lazy';image.style.objectFit='cover';v.append(image);if(t?.preview){const b=button('Смотреть видео',()=>previewTemplate(t),'template-preview-button');b.setAttribute('aria-label','Смотреть шаблон '+t.name);v.append(b)}return v}
function card(p){const c=el('article','project-card'),a=link('','editor.html?project='+encodeURIComponent(p.projectId),'project-image');const image=el('img');image.src=TEMPLATES.find(t=>t.id===p.templateId)?.poster||'assets/demo-'+(p.preset==='product'?'type':p.preset==='dynamic'?'story':'motion')+'.jpg';image.alt='';a.append(image,el('span','project-ratio',p.aspect));if(!p.clips?.length)a.append(el('span','project-empty-label','Пустой проект'));const info=el('div','project-info');info.append(link(p.name,a.href,'project-title'),el('p','',`${p.clips?.length||0} сцен / ${new Date(p.updatedAt).toLocaleDateString('ru-RU')}`));const controls=el('div','project-controls');controls.append(button('Копия',async()=>{const id=makeId();const registered=await registerProject(p.name+' — копия',p.model||'local');await put('project:'+registered.projectId,{...p,projectId:registered.projectId,revision:0,name:p.name+' — копия',updatedAt:new Date().toISOString()});await refresh();render();void 0}),button(p.archived?'Вернуть':'В архив',async()=>{await put('project:'+p.projectId,{...p,archived:!p.archived,revision:(p.revision||0)+1,updatedAt:new Date().toISOString()});await refresh();render();void 0}));info.append(controls);c.append(a,info);return c}
function templateCard(t){const c=el('article','template-card');c.append(poster(t.visual,t.name));const body=el('div','template-body');body.append(el('span','template-tag',t.tag),el('h3','',t.name),el('p','template-description',t.description||''),el('p','',`${t.aspect} / ${t.duration.toLocaleString('ru-RU',{maximumFractionDigits:1})} сек / ${t.category}`),button('Использовать шаблон',()=>newProject(t),'ws-outline'));c.append(body);return c}
async function newProject(template){if(!membership().authenticated){location.href='login.html';return}if(!canCreate()){location.href='pricing.html';return}const d=el('dialog','ws-dialog');d.innerHTML='<form><div class="ws-dialog-head"><h2>Новый проект</h2><button type="button" aria-label="Закрыть">×</button></div><label>Название<input name="name" maxlength="70" required></label><div class="ws-form-row"><label>Формат<select name="aspect"><option>9:16</option><option>16:9</option><option>1:1</option></select></label><label>Длительность<select name="duration"><option value="12">12 секунд — шаблон</option><option value="15">15 секунд</option><option value="30">30 секунд</option><option value="60">60 секунд</option></select></label></div><label>Идея и пожелания<textarea name="brief" rows="4" maxlength="6000"></textarea></label><p>'+(template?'Шаблон добавит монтаж с реальными кадрами, заголовками и переходами. Замените материалы своими.':'Добавьте свои видео и фото в редакторе.')+'</p><div class="ws-dialog-actions"><button type="button" class="ws-outline">Отмена</button><button class="ws-primary" type="submit">Открыть редактор</button></div><p class="ws-form-error" role="alert"></p></form>';
 document.body.append(d);const form=d.querySelector('form');form.elements.name.value=template?.name||'Новый проект';form.elements.aspect.value=template?.aspect||'9:16';if(template){const opt=el('option','',template.duration.toFixed(1)+' секунд — шаблон');opt.value=template.duration;form.elements.duration.append(opt)}form.elements.duration.value=template?.duration||'30';form.elements.brief.value=template?.brief||$('#idea')?.value||'';d.querySelectorAll('[type=button]').forEach(b=>b.onclick=()=>d.close());d.onclose=()=>d.remove();d.showModal();form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{let templateAsset;const importedSources=new Map();if(template?.sourceMedia){for(const source of template.sourceMedia){const response=await fetch(source.url);if(!response.ok)throw Error('Исходник шаблона недоступен');const file=await response.blob();const a={...source,id:makeId(),type:'video',file,poster:source.poster||template.poster,size:file.size};await putAsset(a);importedSources.set(source.id,a.id)}}if(template?.preview&&!template.sourceMedia?.length){const response=await fetch(template.preview);if(!response.ok)throw new Error('Не удалось загрузить шаблон');const file=await response.blob();templateAsset={id:makeId(),name:template.name+' / видео',type:'video',duration:template.duration,width:template.width,height:template.height,file,poster:template.poster,size:file.size}}const p=blankProject({name:form.elements.name.value.trim(),aspect:form.elements.aspect.value,preset:template?.preset||'dynamic',brief:form.elements.brief.value,targetDuration:Number(form.elements.duration.value)});const model=document.querySelector('#workspace-model')?.value||sessionStorage.getItem('vmet-selected-model')||aiPreferences.model_id||'local';const registered=await registerProject(p.name,model);p.projectId=registered.projectId;if(templateAsset||importedSources.size){if(templateAsset)await putAsset(templateAsset);p.templateId=template.id;p.targetDuration=template.duration;p.cues=template.cues||[];p.captionsEnabled=p.cues.length>0;p.clips=templateAsset?(template.segments||[{start:0,end:template.duration}]).map(seg=>({id:makeId(),assetId:templateAsset.id,start:seg.start,end:seg.end,speed:1,transition:'cut',title:'',textStyle:'clean',textPosition:'bottom'})):[];p.selected=p.clips[0]?.id;if(template.editableSegments?.length&&importedSources.size){p.clips=template.editableSegments.map(seg=>({...seg,id:makeId(),assetId:importedSources.get(seg.sourceId)}));p.selected=p.clips[0].id;p.originalAudio=!!template.originalAudio;if(template.audioFile){const audioResponse=await fetch(template.audioFile);if(!audioResponse.ok)throw Error('Аудио шаблона недоступно');const file=await audioResponse.blob(),a={id:makeId(),name:template.name+' / озвучка и музыка',type:'audio',duration:template.duration,file,size:file.size};await putAsset(a);p.music=a.id;p.musicVolume=1}}}p.model=model==='local'?'':model;p.provider=model==='local'?'local':membership().models.find(m=>m.id===model)?.provider||'custom';p.messages=[{id:makeId(),role:'assistant',text:template?'Шаблон добавлен: исходные кадры, редактируемые заголовки, переходы и звук. Замените кадры своими.':'Проект создан. Добавьте материалы, затем попросите составить план.'}];await put('project:'+p.projectId,p);location.href='editor.html?project='+p.projectId}catch(err){d.querySelector('.ws-form-error').textContent='Не удалось сохранить проект: '+err.message}finally{submit.disabled=false}}}
async function refresh(){data=await projects()}
async function render(keepFocus=false){const root=$('#ws-content');if(page==='ai-settings'){await aiSettingsScreen(root);return}let focusStart=0;if(keepFocus)focusStart=document.activeElement?.selectionStart||0;root.replaceChildren();
 if(page==='workspace'){
  const hero=el('section','workspace-hero');hero.append(el('h1','','Новое видео'),el('p','','Опиши задачу или выбери видеошаблон ниже.'));
  const composer=el('div','start-composer'),input=el('textarea');input.id='idea';input.maxLength=6000;input.placeholder='Например: ролик об автомобиле на 30 секунд — динамичный монтаж, крупные титры и акцент на деталях…';input.setAttribute('aria-label','Идея нового видео');const bottom=el('div','start-composer-bottom');bottom.append(el('span','','Материалы добавляются в редакторе'),button('Создать проект',()=>newProject(),'ws-primary'));const ideaLabel=el('label','idea-label','Идея видео');ideaLabel.htmlFor='idea';composer.append(ideaLabel,input,bottom);const modelRow=el('label','workspace-model');modelRow.append(el('span','','Модель для проекта'));const modelSelect=el('select');modelSelect.id='workspace-model';modelOptions(modelSelect,sessionStorage.getItem('vmet-selected-model')||membership().profile?.default_model);modelSelect.onchange=()=>sessionStorage.setItem('vmet-selected-model',modelSelect.value);modelRow.append(modelSelect);composer.insertBefore(modelRow,bottom);hero.append(composer);if(!canCreate())hero.append(link('Выберите подписку, чтобы создавать видео','pricing.html','subscription-banner'));const chips=el('div','idea-chips');for(const t of TEMPLATES.slice(0,4))chips.append(button(t.tag,()=>newProject(t)));hero.append(chips);root.append(hero);
  const quick=el('div','quick-actions');for(const[label,desc,ic,fn]of [['Пустой проект','Собери монтаж с нуля','plus',()=>newProject()],['Начать с шаблона','Готовая структура истории','grid',()=>location.href='templates.html'],['Смотреть студию','Предпросмотр без создания','play',()=>location.href='editor.html?demo=1']]){const b=button('',fn,'quick-card');b.append(icon(ic),el('strong','',label),el('small','',desc));quick.append(b)}root.append(quick);
  const h=el('div','section-title');h.append(el('h2','','Продолжить работу'),link('Все проекты','projects.html'));root.append(h);const grid=el('div','project-grid');for(const p of data.filter(p=>!p.archived).slice(0,3))grid.append(card(p));root.append(grid.childElementCount?grid:empty('Первая история ждёт','Создай проект или открой демо, чтобы познакомиться со студией.',true));const h2=el('div','section-title');h2.append(el('h2','','От идеи к формату'),link('Все шаблоны','templates.html'));root.append(h2);const tg=el('div','template-grid');TEMPLATES.slice(0,3).forEach(t=>tg.append(templateCard(t)));root.append(tg);
 }else if(page==='projects'){
  root.append(heading('Мои проекты','Истории, к которым хочется вернуться. Автосохранение в этом браузере.'),searchToolbar(['Все','В работе','Архив'],render));const grid=el('div','project-grid');data.filter(p=>(category==='Архив'?p.archived:category==='В работе'?!p.archived:true)&&p.name.toLowerCase().includes(query.toLowerCase())).forEach(p=>grid.append(card(p)));root.append(grid.childElementCount?grid:empty('Здесь пока пусто','Создайте проект или измените фильтр.',true));
 }else if(page==='templates'){
  root.append(heading('Видеошаблоны','Шесть заготовок с реальными кадрами. Посмотри видео, открой в редакторе и замени материалы своими.'),searchToolbar(['Все',...new Set(TEMPLATES.map(t=>t.category))],render));const grid=el('div','template-grid');TEMPLATES.filter(t=>(category==='Все'||t.category===category)&&(t.name+' '+t.tag).toLowerCase().includes(query.toLowerCase())).forEach(t=>grid.append(templateCard(t)));root.append(grid.childElementCount?grid:empty('Шаблон не найден','Измените запрос или категорию.'));
 }else if(page==='brand-kit'){await renderBrandKits(root,{allowed:()=>{if(!canCreate()){location.href='pricing.html';return false}return true}})}else if(page==='exports'){await renderExports(root)}else if(page==='agents'){location.replace('ai-settings.html')}else if(page==='pricing'){await renderPricing(root)}else if(page==='account'){await accountScreen(root)}else if(page==='login'){loginScreen(root)}else renderHelp(root);
 const footer=el('footer','ws-footer');footer.append(el('span','','Let’s make every thing.'),link('Главная сайта','index.html'));root.append(footer);if(keepFocus){const s=$('.ws-search input');s?.focus();s?.setSelectionRange(focusStart,focusStart)}
}
async function renderBrand(root){root.append(heading('Твой визуальный почерк','Цвета, тон и подпись бренда — в одном наборе для новых сцен.'));const form=el('form','brand-form');form.innerHTML='<div class="ws-card"><h2>Основы бренда</h2><label>Название<input name="brandName" maxlength="70" required placeholder="Video Maker Every Thing"></label><label>Фраза / подпись<input name="tagline" maxlength="100" placeholder="Let’s make every thing."></label><div class="ws-form-row"><label>Акцент<input name="accent" type="color" value="#f7bacc"></label><label>Текст<input name="textColor" type="color" value="#f8f6f7"></label><label>Фон<input name="background" type="color" value="#0f0e11"></label></div><label>Тон коммуникации<select name="tone"><option>Спокойный и уверенный</option><option>Энергичный и смелый</option><option>Дружелюбный и простой</option><option>Экспертный и точный</option></select></label><button class="ws-primary" type="submit">Сохранить бренд-кит</button><p class="brand-status" role="status"></p></div><div class="brand-preview"><span>Предпросмотр бренда</span><h2>Твой бренд.<br>Твой характер.</h2><p>Let’s make every thing.</p><div class="preview-colors"><i></i><i></i><i></i></div></div>';root.append(form);const kit=await read('brand-kit')||{};for(const k of ['brandName','tagline','accent','textColor','background','tone'])if(kit[k])form.elements[k].value=kit[k];const update=()=>{const p=form.querySelector('.brand-preview');p.style.background=form.elements.background.value;p.style.color=form.elements.textColor.value;p.querySelector('h2').textContent=form.elements.brandName.value||'Твой бренд. Твой характер.';p.querySelector('p').textContent=form.elements.tagline.value||'Let’s make every thing.';p.querySelectorAll('i').forEach((n,i)=>n.style.background=form.elements[['accent','textColor','background'][i]].value)};form.oninput=update;update();form.onsubmit=async e=>{e.preventDefault();if(!canCreate()){location.href='pricing.html';return}try{await put('brand-kit',Object.fromEntries(new FormData(form)));form.querySelector('.brand-status').textContent='Сохранено. В редакторе нажмите «Бренд-кит», чтобы применить к сцене.';void 0}catch(e){toast(e.message)}}}
async function renderExports(root){root.append(heading('История экспортов','Записи о скачивании в этом браузере. Сами готовые файлы находятся в вашей папке загрузок.'));const rows=(await list()).filter(x=>x?.exportId).sort((a,b)=>b.date.localeCompare(a.date));if(!rows.length){root.append(empty('Пока нет экспортов','Открой проект и сохрани видео, обложку, SRT или JSON.'));return}const wrap=el('div','ws-card export-table');const table=el('table');table.innerHTML='<thead><tr><th>Файл</th><th>Проект</th><th>Формат</th><th>Дата</th><th></th></tr></thead>';const body=el('tbody');for(const r of rows){const tr=el('tr');tr.append(el('td','',r.file),el('td','',r.project),el('td','',r.kind),el('td','',new Date(r.date).toLocaleString('ru-RU')));const td=el('td');td.append(link('Открыть проект','editor.html?project='+encodeURIComponent(r.projectId)));tr.append(td);body.append(tr)}table.append(body);wrap.append(table);root.append(wrap)}
function renderHelp(root){root.append(heading('Уверенно от первого кадра','Как устроена твоя студия и что уже работает.'));const topics=[['Как начать?','Выбери и активируй Lite, Plus или Pro на странице «Подписка». Затем создай проект, добавь видео, фото и музыку. Выбери стиль и формат. Попроси локального помощника составить план или собери сцены вручную.'],['Где мои проекты и файлы?','В IndexedDB этого браузера на этом домене. Другой браузер или домен — отдельное хранилище. Очистка данных удалит локальные проекты. Регулярно экспортируй JSON и сохраняй исходные файлы.'],['Как работает ИИ?','По умолчанию включён локальный планировщик по правилам. Он не распознаёт кадры и речь. Для нейросети нужен серверный адаптер, разрешённая модель, пользователь и API-токен.'],['Какие правки доступны?','Обрезка и разделение сцен, порядок, скорость, текст, переходы появления/сдвига, масштаб, поворот, отражение, яркость, контраст, насыщенность, ручные/SRT субтитры и музыка.'],['Как сохранить версии?','В редакторе нажми «История» и создай контрольную точку. Восстановление заменяет текущую композицию; перед ним автоматически сохраняется ещё одна точка. Это локальная история, не совместная работа.'],['Как экспортировать?','WebM до 3 минут, PNG текущего кадра, SRT, JSON и бриф TXT. Рендер WebM идёт в реальном времени: держи вкладку активной. Отчёт о скачивании есть на странице «Экспорты», сам файл — в загрузках.'],['Есть ли генерация, озвучка, стоки и MP4?','Сейчас это внешние сервисы, не локальные функции. Кнопки не выдают заранее приготовленное видео за генерацию. MCP, облачный рендер MP4, автоматическая транскрипция, 4K/HDR и экспорт Premiere/Resolve/Final Cut пока не реализованы.'],['Как управлять кредитами и акциями?','В закрытой админ-панели: пользователи и роли, модели, кредиты, API-токены, кредитные промокоды и каталог акций. Доступ проверяется сервером; платёжная система и публичные баннеры не подключены.']];const items=el('div','help-topics');for(const[q,a]of topics){const d=el('details','ws-card');d.append(el('summary','',q),el('p','',a));items.append(d)}root.append(items,link('Открыть руководство редактора','EDITOR_GUIDE.md','ws-text-link'))}
try{await loadMembership();await loadAISettings();layout();await refresh();await render();window.VMETStartup?.complete()}catch(e){window.VMETStartup?.error('Студия не загрузилась. Повторите попытку.')}
async function renderPricing(root){
 const m=membership();root.append(heading('Создавай на своих условиях','Lite, Plus или Pro — доступ на 30 дней. Цены в рублях. Оплата криптовалютой USDT TRC20 по курсу платёжного сервиса, без автосписаний.'));
 const intro=el('div','pricing-state');intro.append(el('strong','',m.plan==='free'?'Free — только просмотр':'Текущий тариф: '+m.plan[0].toUpperCase()+m.plan.slice(1)),el('p','',m.canCreate?'Доступ до '+new Date(m.endsAt).toLocaleString('ru-RU')+' / Осталось '+m.videosRemaining+' из '+m.videoLimit+' видео за '+m.periodDays+' дней':'Создание проектов, монтаж, экспорт и запросы ИИ открываются после активации подписки.'));root.append(intro);
 const grid=el('div','pricing-grid');const texts={lite:['Для первых историй','Базовые модели Lite','Проекты, монтаж и экспорт'],plus:['Для регулярного контента','Модели Lite и Plus','Все инструменты монтажа'],pro:['Для большого потока','Все разрешённые модели','Все функции']};
 for(const p of m.plans){const card=el('article','ws-card pricing-card '+(p.id==='plus'?'featured':''));card.append(el('span','pricing-kicker',p.id==='plus'?'ОПТИМАЛЬНЫЙ СТАРТ':'VIDEO MAKER EVERY THING'),el('h2','',p.id[0].toUpperCase()+p.id.slice(1)),el('p','',texts[p.id][0]));const price=el('div','plan-price');price.append(el('strong','',(p.price_minor/100).toLocaleString('ru-RU')),el('span','',' ₽ / 30 дней'));card.append(price);const ul=el('ul');for(const line of [p.video_limit+' видео за '+p.period_days+' дней',p.credits+' кредитов в неделю (до лимита)',...texts[p.id].slice(1),'Нет автосписаний'])ul.append(el('li','',line));card.append(ul);const b=button(m.plan===p.id?'Продлить на 30 дней':'Выбрать '+p.id[0].toUpperCase()+p.id.slice(1),()=>checkout(p),p.id==='plus'?'ws-primary':'ws-outline');b.disabled=!p.enabled;card.append(b);if(!m.paymentReady)card.append(el('small','payment-pending','Подключение оплаты в процессе'));grid.append(card)}root.append(grid);

 renderCreditShop(root,m,checkout);
 if(m.authenticated){try{const {orders}=await customer('/api/billing/orders');if(orders.length){const section=el('section','ws-card order-list');section.append(el('h2','','Мои счета'));for(const o of orders){const row=el('div','order-row');row.append(el('span','',o.plan.toUpperCase()+' / '+new Date(o.created_at).toLocaleDateString('ru-RU')),el('span','',o.status));if(o.pay_address&&!o.activated_at)row.append(button('Открыть счёт',()=>showPayment(o),'ws-outline'));section.append(row)}root.append(section)}}catch(e){root.append(el('p','',e.message))}}
}
async function checkout(plan){
 if(location.origin!==APP_ORIGIN){location.href=APP_ORIGIN+'/pricing.html';return}
 if(!membership().authenticated){location.href='login.html?next=%2Fpricing.html';return}if(!membership().paymentReady){toast('Платёжный сервис ещё не подключён. Счёт не создан.');return}
 try{toast('Создаём счёт…');const {order}=await customer('/api/billing/checkout',plan.pack_id?{pack_id:plan.pack_id}:{plan:plan.id});showPayment(order)}catch(e){toast(e.message)}
}
function showPayment(order){
 const d=el('dialog','ws-dialog payment-dialog');const header=el('div','ws-dialog-head');header.append(el('h2','',order.kind==='credits'?'Покупка '+order.credits+' кредитов':'Оплата '+order.plan.toUpperCase()),button('×',()=>d.close()));d.append(header,el('p','network-label',(order.price_currency==='rub'?(order.price_minor/100).toLocaleString('ru-RU')+' ₽ · ':'')+'USDT / TRON (TRC20)'));
 for(const [label,value]of [['Точная сумма USDT',order.pay_amount],['Адрес получателя',order.pay_address]]){const box=el('div','payment-detail');box.append(el('small','',label),el('code','',value),button('Копировать',()=>navigator.clipboard.writeText(value).then(()=>toast('Скопировано')).catch(()=>toast('Выделите и скопируйте значение вручную'))));d.append(box)}
 d.append(el('p','','Переводите только USDT в сети TRON (TRC20). Другой актив или сеть не активируют подписку. Не отправляйте повторный перевод, если платёж подтверждается.'));
 const status=el('p','payment-status',order.status),check=button('Проверить платёж',async()=>{check.disabled=true;try{const r=await customer('/api/billing/check',{order_id:order.id});status.textContent=r.activated?(order.kind==='credits'?'Кредиты зачислены':'Подписка активирована'):r.status+(r.retryAfter?' / повторите через 10 секунд':'');if(r.activated){await loadMembership();d.close();render();toast(order.kind==='credits'?'Кредиты зачислены':'Подписка активирована')}}catch(e){status.textContent=e.message}finally{check.disabled=false}},'ws-primary');d.append(status,check);document.body.append(d);d.onclose=()=>d.remove();d.showModal();
}



